class Bitmap:
    def __init__(self):
        self.buf = bytearray()
    def setbit(self, off, val):
        byte = off // 8; bit = off % 8
        while len(self.buf) <= byte:
            self.buf.append(0)
        if val:
            self.buf[byte] |= (1 << (7 - bit))
        else:
            self.buf[byte] &= ~(1 << (7 - bit))
    def getbit(self, off):
        byte = off // 8; bit = off % 8
        if byte >= len(self.buf):
            return 0
        return (self.buf[byte] >> (7 - bit)) & 1

bm = Bitmap()
bm.setbit(3, 1)
bm.setbit(10, 1)
print("after set 3,10: bytes =", list(bm.buf))
print("getbit 3 =", bm.getbit(3), " getbit 10 =", bm.getbit(10), " getbit 0 =", bm.getbit(0))
bm.setbit(20, 1)
print("after set 20: len(bytes) =", len(bm.buf))
